using System.Text.Json.Serialization;
using Microsoft.AspNetCore.Http.HttpResults;
using ProductsApi.Models;
using ProductsApi.Services;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton<IProductService, InMemoryProductService>();
builder.Services.AddOpenApi();
builder.Services.ConfigureHttpJsonOptions(options =>
{
    options.SerializerOptions.Converters.Add(new JsonStringEnumConverter());
});

var app = builder.Build();

app.MapOpenApi();

var products = app.MapGroup("/api/products")
    .WithTags("Products");

products.MapGet("/", (IProductService svc) => svc.GetAll())
    .WithName("GetAllProducts")
    .WithSummary("List all products")
    .WithDescription("Returns the complete list of products currently stored in the system.");

products.MapGet("/{id:guid}", Results<Ok<Product>, NotFound> (Guid id, IProductService svc) =>
    {
        var product = svc.GetById(id);
        return product is not null ? TypedResults.Ok(product) : TypedResults.NotFound();
    })
    .WithName("GetProductById")
    .WithSummary("Get a product by ID")
    .WithDescription("Returns a single product matching the specified unique identifier, or 404 if not found.");

products.MapPost("/", Created<Product> (CreateProductRequest request, IProductService svc) =>
    {
        var product = svc.Create(request);
        return TypedResults.Created($"/api/products/{product.Id}", product);
    })
    .WithName("CreateProduct")
    .WithSummary("Create a new product")
    .WithDescription("Creates a new product with the supplied name, price, and category. Returns the created product with its generated ID and timestamp.");

app.Run();

